mapper.select:
select case when exists(
    select 1 from T_SYNC_MPS_2_APS_FAC
        where
        year = #{year,jdbcType=NUMERIC}
        AND month = #{month,jdbcType=NUMERIC}
        AND production_version = #{productionVersion,jdbcType=VARCHAR}
        AND is_delete = 0
        AND factory_code = 'L6'
    ) then 1 else 0 end
from dual

mapper.update:
merge into T_SERVICE_SYNC_LOG a USING (
select #{ITEM.id,jdbcType=DECIMAL} ID, #{ITEM.serviceType,jdbcType=CHAR} SERVICE_TYPE, #{ITEM.serviceStatus,jdbcType=CHAR} SERVICE_STATUS, #{ITEM.serviceParams,jdbcType=VARCHAR} SERVICE_PARAMS, #{ITEM.serviceResult,jdbcType=VARCHAR} SERVICE_RESULT, #{ITEM.createBy,jdbcType=VARCHAR} CREATE_BY, #{ITEM.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{ITEM.updateBy,jdbcType=VARCHAR} UPDATE_BY, #{ITEM.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{ITEM.delFlag,jdbcType=CHAR} DEL_FLAG, #{ITEM.remark,jdbcType=VARCHAR} REMARK from dual
) b ON ( a.id = b.id and b.CREATE_TIME = a.CREATE_TIME AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.SERVICE_TYPE = b.SERVICE_TYPE, a.SERVICE_STATUS = b.SERVICE_STATUS, a.SERVICE_PARAMS = b.SERVICE_PARAMS, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.SERVICE_TYPE, a.SERVICE_STATUS, a.SERVICE_PARAMS, a.SERVICE_RESULT, a.CREATE_BY, a.CREATE_TIME, a.UPDATE_BY, a.UPDATE_TIME, a.DEL_FLAG, a.REMARK) values (SEQ_SERVICE_SYNC_LOG.NEXTVAL, b.SERVICE_TYPE, b.SERVICE_STATUS, b.SERVICE_PARAMS, b.SERVICE_RESULT, b.CREATE_BY, b.CREATE_TIME, b.UPDATE_BY, sysdate, '0', b.REMARK)
